{
  "schemaVersion": "ride-output-v2.2.0",
  "label": {
    "text": "总距离 161.8 公里的长距离骑行",
    "conclusionType": "fact",
    "claimIds": ["claim:demo-ride-2026-07-22:v2:metric.distanceM"]
  },
  "overallAssessment": {
    "text": "本次骑行总距离 161.8 公里，移动时长 6 小时 40 分钟，累计爬升 2924 米，整体是一次高强度、大负荷的长距离骑行。",
    "conclusionType": "fact",
    "claimIds": ["claim:demo-ride-2026-07-22:v2:metric.distanceM", "claim:demo-ride-2026-07-22:v2:timing.movingDurationS", "claim:demo-ride-2026-07-22:v2:metric.elevationGainM"]
  },
  "highlights": [
    {
      "text": "本次骑行累计爬升 2924 米，包含 15 个爬坡段，其中 3 个代表性爬坡难度较高。",
      "conclusionType": "fact",
      "claimIds": ["claim:demo-ride-2026-07-22:v2:metric.elevationGainM", "claim:demo-ride-2026-07-22:v2:climb.representativeClimbCount"]
    },
    {
      "text": "10 秒峰值平均功率达到 566W，20 秒为 538W，30 秒为 516W，短时爆发力表现突出。",
      "conclusionType": "fact",
      "claimIds": ["claim:demo-ride-2026-07-22:v2:power.peakAverage.10s", "claim:demo-ride-2026-07-22:v2:power.peakAverage.20s", "claim:demo-ride-2026-07-22:v2:power.peakAverage.30s"]
    }
  ],
  "dimensions": [
    {
      "dimensionId": "pacingExecution",
      "assertions": [
        {
          "text": "本次骑行移动时长 6 小时 40 分钟，总用时 7 小时 2 分钟，中途停车 14 次。",
          "conclusionType": "fact",
          "claimIds": ["claim:demo-ride-2026-07-22:v2:timing.movingDurationS", "claim:demo-ride-2026-07-22:v2:metric.elapsedDurationS", "claim:demo-ride-2026-07-22:v2:stops.count"]
        },
        {
          "text": "平均速度 24.06 km/h，速度变异系数 49.2%，速度波动较大。",
          "conclusionType": "fact",
          "claimIds": ["claim:demo-ride-2026-07-22:v2:speed.mean", "claim:demo-ride-2026-07-22:v2:speed.coefficientOfVariation"]
        },
        {
          "text": "巡航段平均速度 29.33 km/h，功率 143W；另一巡航段平均速度 26.7 km/h，功率 137W。",
          "conclusionType": "fact",
          "claimIds": ["claim:demo-ride-2026-07-22:v2:segment.cruise.cruise-0-23950.speed.mean", "claim:demo-ride-2026-07-22:v2:segment.cruise.cruise-0-23950.power.mean", "claim:demo-ride-2026-07-22:v2:segment.cruise.cruise-1-24179.speed.mean", "claim:demo-ride-2026-07-22:v2:segment.cruise.cruise-1-24179.power.mean"]
        },
        {
          "text": "地形分类覆盖率为 100%，其中爬坡段 24 个、平路段 41 个、下坡段 22 个。",
          "conclusionType": "fact",
          "claimIds": ["claim:demo-ride-2026-07-22:v2:terrain.classifiedCoverageRatio", "claim:demo-ride-2026-07-22:v2:terrain.climbRunCount", "claim:demo-ride-2026-07-22:v2:terrain.flatRunCount", "claim:demo-ride-2026-07-22:v2:terrain.descentRunCount"]
        },
        {
          "text": "整体配速受地形影响明显，爬坡段速度明显低于平路和下坡段，符合地形特征。",
          "conclusionType": "interpretation",
          "claimIds": ["claim:demo-ride-2026-07-22:v2:segment.terrain.terrain-climb-11010.4-21690.93.speed.mean", "claim:demo-ride-2026-07-22:v2:segment.terrain.terrain-flat-7560.97-11010.4.speed.mean", "claim:demo-ride-2026-07-22:v2:segment.terrain.terrain-descent-62593.25-70758.08.speed.mean"]
        }
      ]
    },
    {
      "dimensionId": "climbPerformance",
      "assertions": [
        {
          "text": "本次骑行累计爬升 2924 米，累计下降 2808 米，爬坡段总距离 70.2 公里，平路 16.1 公里，下坡 73.3 公里。",
          "conclusionType": "fact",
          "claimIds": ["claim:demo-ride-2026-07-22:v2:metric.elevationGainM", "claim:demo-ride-2026-07-22:v2:metric.elevationLossM", "claim:demo-ride-2026-07-22:v2:terrain.trendClimbDistanceM", "claim:demo-ride-2026-07-22:v2:terrain.trendFlatDistanceM", "claim:demo-ride-2026-07-22:v2:terrain.trendDescentDistanceM"]
        },
        {
          "text": "代表性爬坡中，最难的爬坡段平均坡度 11.1%，难度评分 509，用时 25 分钟，平均功率 256W，平均速度 9.9 km/h。",
          "conclusionType": "fact",
          "claimIds": ["claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-84688-88849.averageGrade", "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-84688-88849.difficultyScore", "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-84688-88849.span", "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-84688-88849.power.mean", "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-84688-88849.speed.mean"]
        },
        {
          "text": "另一爬坡段平均坡度 5.7%，难度评分 268，用时 38 分钟，平均功率 185W，平均速度 13.26 km/h。",
          "conclusionType": "fact",
          "claimIds": ["claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-37936-46050.averageGrade", "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-37936-46050.difficultyScore", "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-37936-46050.span", "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-37936-46050.power.mean", "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-37936-46050.speed.mean"]
        },
        {
          "text": "爬坡段功率输出较高，在陡坡段能维持较高功率，爬坡表现整体扎实。",
          "conclusionType": "interpretation",
          "claimIds": ["claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-84688-88849.power.mean", "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-37936-46050.power.mean"]
        }
      ]
    },
    {
      "dimensionId": "powerOutput",
      "assertions": [
        {
          "text": "平均功率 151W，归一化功率 197W，功率变异系数 66.1%，功率波动较大。",
          "conclusionType": "fact",
          "claimIds": ["claim:demo-ride-2026-07-22:v2:power.mean", "claim:demo-ride-2026-07-22:v2:power.normalizedW", "claim:demo-ride-2026-07-22:v2:power.coefficientOfVariation"]
        },
        {
          "text": "功率区间分布：Z1 占 27%，Z2 占 14%，Z3 占 18%，Z4 占 17%，Z5 占 10%，Z6 占 9%，Z7 占 5%，高强度区间（Z5-Z7）合计占 24%。",
          "conclusionType": "fact",
          "claimIds": ["claim:demo-ride-2026-07-22:v2:power.zone.z1", "claim:demo-ride-2026-07-22:v2:power.zone.z2", "claim:demo-ride-2026-07-22:v2:power.zone.z3", "claim:demo-ride-2026-07-22:v2:power.zone.z4", "claim:demo-ride-2026-07-22:v2:power.zone.z5", "claim:demo-ride-2026-07-22:v2:power.zone.z6", "claim:demo-ride-2026-07-22:v2:power.zone.z7", "claim:demo-ride-2026-07-22:v2:power.zone.highIntensityCombined"]
        },
        {
          "text": "功率与速度在同一时间窗内的覆盖率为 99%，功率和速度数据在时间上高度同步。",
          "conclusionType": "fact",
          "claimIds": ["claim:demo-ride-2026-07-22:v2:relation.fixed.power-speed.aggregate"]
        },
        {
          "text": "功率输出整体偏高，高强度区间占比达 24%，说明本次骑行强度较大。",
          "conclusionType": "interpretation",
          "claimIds": ["claim:demo-ride-2026-07-22:v2:power.zone.highIntensityCombined"]
        }
      ]
    },
    {
      "dimensionId": "intensityAndTrainingLoad",
      "assertions": [
        {
          "text": "本次骑行强度因子 0.99，训练压力评分 640.2，活动消耗 4439 千卡。",
          "conclusionType": "fact",
          "claimIds": ["claim:demo-ride-2026-07-22:v2:power.intensityFactor", "claim:demo-ride-2026-07-22:v2:power.trainingStressScore", "claim:demo-ride-2026-07-22:v2:metric.activityEnergyKcal"]
        },
        {
          "text": "平均功率 151W，相对功率 2.15 W/kg，归一化功率 197W，相对归一化功率 2.82 W/kg。",
          "conclusionType": "fact",
          "claimIds": ["claim:demo-ride-2026-07-22:v2:power.mean", "claim:demo-ride-2026-07-22:v2:power.averageWkg", "claim:demo-ride-2026-07-22:v2:power.normalizedW", "claim:demo-ride-2026-07-22:v2:power.normalizedWkg"]
        },
        {
          "text": "本次骑行训练负荷较高，强度因子接近 1.0，训练压力评分超过 600，属于大负荷骑行。",
          "conclusionType": "interpretation",
          "claimIds": ["claim:demo-ride-2026-07-22:v2:power.intensityFactor", "claim:demo-ride-2026-07-22:v2:power.trainingStressScore"]
        }
      ]
    },
    {
      "dimensionId": "cadenceStrategy",
      "assertions": [
        {
          "text": "平均踏频 76 rpm，踏频变异系数 15.3%，踏频分布以耐力区间为主（44%），稳定区间占 37%。",
          "conclusionType": "fact",
          "claimIds": ["claim:demo-ride-2026-07-22:v2:cadence.mean", "claim:demo-ride-2026-07-22:v2:cadence.coefficientOfVariation", "claim:demo-ride-2026-07-22:v2:cadence.zone.endurance", "claim:demo-ride-2026-07-22:v2:cadence.zone.steady"]
        },
        {
          "text": "踏频数据部分缺失，平均踏频 76 rpm 为软性数据，解读时需谨慎。",
          "conclusionType": "fact",
          "claimIds": ["claim:demo-ride-2026-07-22:v2:cadence.mean"]
        }
      ]
    },
    {
      "dimensionId": "crossSensorCoordination",
      "assertions": [
        {
          "text": "功率与速度在同一时间窗内的覆盖率为 99%，代表性窗口的覆盖率分别为 100%、100% 和 77%。",
          "conclusionType": "fact",
          "claimIds": ["claim:demo-ride-2026-07-22:v2:relation.fixed.power-speed.aggregate", "claim:demo-ride-2026-07-22:v2:relation.fixed.power-speed.rep.2", "claim:demo-ride-2026-07-22:v2:relation.fixed.power-speed.rep.3", "claim:demo-ride-2026-07-22:v2:relation.fixed.power-speed.rep.159"]
        },
        {
          "text": "功率与速度数据在时间上高度同步，说明传感器记录一致性较好。",
          "conclusionType": "interpretation",
          "claimIds": ["claim:demo-ride-2026-07-22:v2:relation.fixed.power-speed.aggregate"]
        }
      ]
    }
  ],
  "suggestions": [
    {
      "text": "本次骑行训练负荷较高，建议后续安排适当恢复，避免连续高强度训练。",
      "conclusionType": "suggestion",
      "claimIds": ["claim:demo-ride-2026-07-22:v2:power.trainingStressScore"],
      "riskNote": "恢复建议基于单次负荷，不构成恢复状态判断。"
    },
    {
      "text": "下次骑行可尝试在平路段保持更稳定的功率输出，以减少功率波动。",
      "conclusionType": "suggestion",
      "claimIds": ["claim:demo-ride-2026-07-22:v2:power.coefficientOfVariation"]
    }
  ],
  "limitations": [
    "terrain.climbRunCount:AGGREGATED_FROM_24_WINDOWS",
    "terrain.flatRunCount:AGGREGATED_FROM_41_WINDOWS",
    "terrain.descentRunCount:AGGREGATED_FROM_22_WINDOWS",
    "heartRate:SERIES_MISSING",
    "climb.representativeClimbCount:AGGREGATED_FROM_15_WINDOWS",
    "relation.fixed.power-speed.aggregate:AGGREGATED_FROM_776_WINDOWS"
  ]
}
